/bin/bash -lc "node <<'NODE'
const assert = require('node:assert/strict');
const { merge_intervals } = require('./logic');
const cases = [
  [[[8, 9], [1, 2], [3, 4]], [[1, 2], [3, 4], [8, 9]]],
  [[[1, 10], [2, 3], [1, 10], [10, 10]], [[1, 10]]],
  [[[5, 5], [3, 5], [-2, 3]], [[-2, 5]]],
  [[[0, 0]], [[0, 0]]],
  [[], []]
];
for (const [input, expected] of cases) {
  const before = JSON.stringify(input);
  input.forEach(Object.freeze);
  Object.freeze(input);
  const actual = merge_intervals(input);
  assert.deepEqual(actual, expected);
  assert.equal(JSON.stringify(input), before);
  for (const interval of actual) assert.ok("'!input.includes(interval));
}
console.log('"'Additional edge cases passed.');
NODE"

